  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']

    # Build a dict for quick distance lookup, canonical order (smaller, larger)
    dist_lookup = {}
    for a, b, d in dists:
        if a < b:
            key = (a, b)
        else:
            key = (b, a)
        dist_lookup[key] = d

    # Build all edges with mutual reachability
    edges = []
    n = len(nodes)
    for i in range(n):
        for j in range(i+1, n):
            u = nodes[i]
            v = nodes[j]
            if u < v:
                key = (u, v)
            else:
                key = (v, u)
            dist = dist_lookup.get(key)
            if dist is None:
                # edge not provided (should not happen)
                continue
            mr = max(core[u], core[v], dist)
            edges.append((mr, u, v))

    # Sort edges: primary by weight, secondary by endpoint IDs (canonical)
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, u, v in edges:
        if union(u, v):
            # store as [u, v, weight] with u < v (canonical order)
            if u < v:
                mst_edges.append([u, v, weight])
            else:
                mst_edges.append([v, u, weight])
            total_weight += weight
            if len(mst_edges) == n - 1:
                break

    # If graph is disconnected (should not happen in valid input), return empty
    if len(mst_edges) != n - 1:
        mst_edges = []
        total_weight = 0.0

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
